record.field:
if not record.department_id:
    allowed_departments = user.allowed_department_ids
    if allowed_departments:
        if len(allowed_departments) == 1:
            record.department_id = allowed_departments[0].id
        else:
            raise UserError("Tienes múltiples departamentos asignados. Por favor selecciona manualmente el departamento correspondiente en la orden de compra.")
